@ExtendWith(MockitoExtension.class)
class OrderServiceTest {
    @Mock
    private OrderRepository orderRepository;

    @InjectMocks
    private OrderService orderService;

    @Test
    void shouldReturnOrderWhenFound() {
        var orderId = 123L;
        var expectedOrder = new Order(orderId, "Laptop", 999.99);

        // Arrange: stub the repository method
        when(orderRepository.findById(orderId)).thenReturn(Optional.of(expectedOrder));

        // Act: call the service method
        var result = orderService.getOrderDetails(orderId);

        // Assert: verify the result
        assertEquals("Laptop", result.getItem());
        verify(orderRepository).findById(orderId); // verify interaction
    }
}

@ExtendWith(MockitoExtension.class)
class PaymentServiceTest {
    @Mock
    private PaymentGateway paymentGateway;

    @InjectMocks
    private PaymentService paymentService;

    @Test
    void shouldWrapGatewayExceptionInBusinessException() {
        var payment = new Payment(100.0, "USD");

        // Stub the gateway to throw a network exception
        when(paymentGateway.processPayment(payment))
            .thenThrow(new GatewayTimeoutException("Network unreachable"));

        // Verify service wraps it in a business exception
        var exception = assertThrows(PaymentFailedException.class, 
            () -> paymentService.processPayment(payment));

        assertTrue(exception.getMessage().contains("Gateway unavailable"));
        verify(paymentGateway).processPayment(payment);
    }
}

@ExtendWith(MockitoExtension.class)
class CustomerServiceTest {
    @Mock
    private CustomerRepository customerRepository;

    @InjectMocks
    private CustomerService customerService;

    @Test
    void shouldReturnCustomerWithGeneratedId() {
        var newCustomer = new Customer(null, "Alice", "alice@example.com");

        // Stub save to return the input customer with a generated ID
        when(customerRepository.save(any(Customer.class)))
            .thenAnswer(invocation -> {
                Customer input = invocation.getArgument(0);
                return new Customer(999L, input.getName(), input.getEmail());
            });

        var saved = customerService.createCustomer(newCustomer);

        assertNotNull(saved.getId());
        assertEquals("Alice", saved.getName());
        verify(customerRepository).save(newCustomer);
    }
}

@ExtendWith(MockitoExtension.class)
class MockDefaultBehaviorTest {
    @Mock
    private UserRepository userRepository;

    @Test
    void demonstrateDefaultMockReturns() {
        // None of these methods are stubbed

        User user = userRepository.findById(1L).orElse(null);
        assertNull(user); // Optional.empty() is returned

        List<User> users = userRepository.findAll();
        assertTrue(users.isEmpty()); // Empty list, not null

        int count = userRepository.count();
        assertEquals(0, count); // Primitive int returns 0

        boolean exists = userRepository.existsByEmail("test@example.com");
        assertFalse(exists); // Boolean returns false

        // No exception thrown for any non-stubbed method
        verify(userRepository).findById(1L); // Interaction still recorded
    }
}

@ExtendWith(MockitoExtension.class)
class NotificationServiceTest {
    @Mock
    private EmailSender emailSender;

    @Mock
    private AuditLogger auditLogger;

    @InjectMocks
    private NotificationService notificationService;

    @Test
    void shouldHandleEmailSendingFailure() {
        var message = "Order confirmed";

        // Stub void method to throw exception
        doThrow(new EmailException("SMTP server unavailable"))
            .when(emailSender).send(anyString(), anyString());

        assertThrows(NotificationException.class, 
            () -> notificationService.sendOrderConfirmation("user@example.com", message));
    }

    @Test
    void shouldCaptureAuditLogArguments() {
        var logs = new ArrayList<String>();

        // Use doAnswer to capture what was logged
        doAnswer(inv -> logs.add(inv.getArgument(0)))
            .when(auditLogger).log(anyString());

        notificationService.processOrder(123L);

        assertTrue(logs.contains("Order 123 processed"));
    }
}

@ExtendWith(MockitoExtension.class)
class PaymentRetryServiceTest {
    @Mock
    private PaymentGateway paymentGateway;

    @InjectMocks
    private PaymentRetryService paymentService;

    @Test
    void shouldRetryAndSucceedOnSecondAttempt() {
        var payment = new Payment(100.0, "USD");
        var successResponse = new PaymentResponse("txn-123", "SUCCESS");

        // First call fails, second call succeeds
        when(paymentGateway.processPayment(payment))
            .thenThrow(new GatewayTimeoutException("Timeout"))
            .thenReturn(successResponse);

        var result = paymentService.processWithRetry(payment, 3);

        assertEquals("SUCCESS", result.getStatus());
        verify(paymentGateway, times(2)).processPayment(payment); // Called twice
    }

    @Test
    void shouldHandlePagination() {
        when(orderRepository.findPage(anyInt()))
            .thenReturn(List.of("Order1", "Order2"))
            .thenReturn(List.of("Order3"))
            .thenReturn(List.of()); // Empty signals end

        var allOrders = orderService.fetchAllOrders();

        assertEquals(3, allOrders.size());
        verify(orderRepository, times(3)).findPage(anyInt());
    }
}
